<?php

namespace App\Http\Controllers;

use App\Billing\CreditLedger;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;

/** The fake "Buy credits" button: adds one fixed pack, no payment involved. */
class CreditPurchaseController extends Controller
{
    public function __invoke(Request $request, CreditLedger $ledger): RedirectResponse
    {
        // Generated by the browser per click intent, so a double click (or a retried request) credits once.
        $input = $request->validate(['idempotency_key' => ['required', 'uuid']]);

        $ledger->purchase($request->user(), config('pixelforge.credit_pack_nano'), $input['idempotency_key']);

        return to_route('generations.index');
    }
}
